def calculate_b_squared(x):
    # b^2 = (x^3 + 4x^2 + 3x - 2) / x
    if x == 0:
        return "Undefined"
    numerator = x**3 + 4*x**2 + 3*x - 2
    b_squared = numerator / x
    return b_squared

test_values = [1, 2, 3, -1, -2]
results = {}
for x in test_values:
    results[x] = calculate_b_squared(x)

print(results)
